function ensureMapPanel(){if($('#regionMap'))return;const panel=document.createElement('section');panel.id='regionMap';panel.className='region-map hidden';panel.innerHTML='<div class="region-map-head"><b>MAPA DE CAMPO</b><button id="pinPosition">MARCAR POSICAO</button></div><div id="regionList"></div><div id="mapPins"></div>';$('.journal')?.before(panel);$('#pinPosition').onclick=()=>{if(!bag.map){setMessage('Encontre o mapa nos destrocos primeiro.');return}mapMarkers.push({x:Math.round(camera.position.x),z:Math.round(camera.position.z),region:regionAt(camera.position.x,camera.position.z).name});updateMapPanel();saveGame();setMessage('Local marcado no mapa.')};updateMapPanel()}function openMap(){if(!bag.map){setMessage('Encontre e pegue o mapa de papel perto dos destrocos, depois pressione M para le-lo.');return}ensureMapPanel();const panel=$('#inventoryPanel');panel.classList.remove('hidden');inventoryOpen=true;document.exitPointerLock?.();$('#regionMap').classList.remove('hidden');updateMapPanel()}function updateMapPanel(){const list=$('#regionList');if(!list)return;list.innerHTML=regions.map(r=>'<div class="region-row '+(discoveredRegions.has(r.id)?'found':'')+'"><span>'+(discoveredRegions.has(r.id)?'OK':'?')+'</span><b>'+(discoveredRegions.has(r.id)||bag.map?r.name:'Local nao identificado')+'</b>'+(bag.map&&discoveredRegions.has(r.id)?'<small>'+r.x+', '+r.z+'</small>':'')+'</div>').join('');$('#mapPins').innerHTML=mapMarkers.map(m=>'<div class="pin-row">? '+m.region+' ('+m.x+', '+m.z+')</div>').join('')||'<small>Nenhum ponto marcado.</small>'}function updateRegionDiscovery(){const r=regionAt(camera.position.x,camera.position.z);if(!r)return regions[0];if(Math.hypot(camera.position.x-r.x,camera.position.z-r.z)<r.r*.45&&!discoveredRegions.has(r.id)){discoveredRegions.add(r.id);setMessage('Regiao descoberta: '+r.name);updateMapPanel();saveGame()}return r}function renderObjectives(){const box=$('#missionList');if(!box)return;for(const g of bonusGoals){if(g.test()&&!claimedGoals.has(g.id)){claimedGoals.add(g.id);g.give();setMessage('Meta concluida: '+g.name+' (+'+g.reward+')');updateInventory();saveGame()}}const available=missionSteps.filter((m,i)=>i===0||missionSteps[i-1].done());const html=available.map((m,i)=>`<div class="mission-row ${m.done()?'done':''} ${missionSteps.findIndex(x=>!x.done())===i?'active':''}"><span>${m.done()?'OK':String(i+1).padStart(2,'0')}</span><p>${m.text}</p></div>`).join('');const goals='<div class="bonus-title">METAS OPCIONAIS</div>'+bonusGoals.map(g=>'<div class="bonus-row '+(claimedGoals.has(g.id)?'claimed':'')+'"><span>'+(claimedGoals.has(g.id)?'OK':'+')+'</span><p>'+g.name+' <small>'+g.reward+'</small></p></div>').join('');if(html+goals!==missionCache){box.innerHTML=html+goals;missionCache=html+goals}const index=missionSteps.findIndex(m=>!m.done());$('#objective').textContent=escaped?'Jornada concluida':index<0?'Voce escapou da floresta':missionSteps[index].text;$('#objectiveSub').textContent=index<0?'A jornada terminou.':`Etapa ${index+1} de ${missionSteps.length} - complete para avancar.`}
function discardItem(k,amount){amount=Math.floor(Number(amount));if(!Number.isFinite(amount)||amount<1||amount>bag[k]){setMessage('Quantidade invalida para descarte.');return}if((amount>=5||['key','map','sword','axe','hoe'].includes(k))&&!confirm('Descartar '+amount+' '+(names[k]||k)+'?'))return;bag[k]-=amount;const x=camera.position.x-Math.sin(yaw)*1.8,z=camera.position.z-Math.cos(yaw)*1.8;addResource(x,z,k,names[k]||k,amount);updateInventory();saveGame();setMessage(amount+' '+(names[k]||k)+' descartado(s) no chao.')}
function setMessage(t){const m=$('#message');m.textContent=t;m.classList.add('show');clearTimeout(setMessage.timer);setMessage.timer=setTimeout(()=>m.classList.remove('show'),2600)}
function endGame(win,title,txt){gameEnded=true;paused=true;if(win){escaped=true;saveGame()}document.exitPointerLock?.();if(!win&&!$('#loadEnd')){const b=document.createElement('button');b.id='loadEnd';b.className='primary';b.textContent='CARREGAR SALVAMENTO';b.onclick=()=>location.reload();$('#restart').after(b)}if(win&&!$('#freeExplore')){const b=document.createElement('button');b.id='freeExplore';b.className='primary';b.textContent='CONTINUAR EXPLORANDO';b.onclick=()=>{gameEnded=false;paused=false;$('#endScreen').classList.add('hidden');setMessage('Modo livre: continue explorando e construindo seu acampamento.');renderer.domElement.requestPointerLock?.()};$('#restart').after(b)}$('#endLabel').textContent=win?'EXPEDICAO CONCLUIDA':'JORNADA INTERROMPIDA';$('#endTitle').textContent=title;if(win)txt+='\n\nDias sobrevividos: '+day+'\nEstruturas construidas: '+structures.length+'\nRegioes exploradas: '+discoveredRegions.size+'\nRecursos coletados: '+Object.values(progress).reduce((a,b)=>a+b,0)+'\nEstacao de radio: '+(radioRepaired?'reparada':'nao reparada')+'\nDocumentos encontrados: '+clues.size;$('#endText').textContent=txt;$('#endScreen').classList.remove('hidden')}
function start(){started=true;paused=false;inventoryOpen=false;overlay.classList.add('hidden');hud.classList.remove('hidden');try{ensureAudio();renderer.domElement.requestPointerLock?.()}catch(e){console.warn('Pointer lock/audio unavailable',e)}setMessage('Tempestade danificou seu equipamento. Encontre agua e monte um abrigo.');try{updateInventory()}catch(e){console.error('Inventory initialization failed',e)}}
const people=[{id:'scout',name:'Lia',role:'BATEDORA',perk:'Coleta +1 unidade por recurso',icon:'*'},{id:'runner',name:'Davi',role:'CORREDOR',perk:'Corre gastando menos energia',icon:'>'},{id:'medic',name:'Nina',role:'SOCORRISTA',perk:'Comeca com 2 ervas medicinais',icon:'+'}];const picker=document.querySelector('.character-picker')||document.createElement('div');picker.className='character-picker';picker.innerHTML='<span class="label">ESCOLHA SUA EQUIPE DE EXPEDICAO</span><div class="character-cards"></div>';for(const person of people){const card=document.createElement('button');card.className='character-card';card.dataset.id=person.id;card.innerHTML='<span class="char-icon">'+person.icon+'</span><b>'+person.name+'</b><small>'+person.role+'</small><em>'+person.perk+'</em>';card.onclick=()=>{selectedCharacter=person.id;safeStorage.set('forest-character',selectedCharacter);document.querySelectorAll('.character-card').forEach(c=>c.classList.toggle('selected',c.dataset.id===selectedCharacter))};picker.querySelector('.character-cards').appendChild(card)}$('.title-card').insertBefore(picker,$('#start'));document.querySelectorAll('.character-card').forEach(c=>c.classList.toggle('selected',c.dataset.id===selectedCharacter));$('#start').textContent=safeStorage.get('sete-dias-save')?'CONTINUAR':'INICIAR JOGO';$('#start').addEventListener('click',()=>{try{const loaded=loadGame();if(!loaded&&selectedCharacter==='medic')bag.herb+=2}catch(e){console.error('Save load failed',e)}start()});const newBtn=$('#newGame')||document.createElement('button');newBtn.className='primary';newBtn.textContent='NOVO JOGO';newBtn.style.marginLeft='10px';newBtn.onclick=()=>{if(confirm('Iniciar uma nova jornada? O salvamento atual sera substituido.')){safeStorage.remove('sete-dias-save');safeStorage.set('forest-character',selectedCharacter);location.reload()}};$('#start').after(newBtn);$('#restart').addEventListener('click',()=>location.reload());$('#pauseBtn').addEventListener('click',()=>{paused=!paused;if(paused)document.exitPointerLock?.();else renderer.domElement.requestPointerLock?.()});
renderer.domElement.addEventListener('click',()=>{if(started&&!paused&&!inventoryOpen&&document.pointerLockElement!==renderer.domElement)renderer.domElement.requestPointerLock?.()});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement&&!inventoryOpen&&!paused){yaw-=e.movementX*.0022;pitch-=e.movementY*.0018;pitch=THREE.MathUtils.clamp(pitch,-1.45,1.45)}});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='Space'&&started&&!paused&&!inventoryOpen&&camera.position.y<=terrainHeight(camera.position.x,camera.position.z)+1.71)jumpVelocity=6;if(e.code==='Tab'||e.code==='KeyI'){e.preventDefault();if(started&&!gameEnded){inventoryOpen=!inventoryOpen;$('#inventoryPanel').classList.toggle('hidden',!inventoryOpen);if(inventoryOpen)document.exitPointerLock?.();else renderer.domElement.requestPointerLock?.()}}if(e.code==='Escape'&&started&&!inventoryOpen)paused=!paused;if(e.code==='KeyF'&&started){flashOn=!flashOn;flashlight.intensity=flashOn?5.5:0;setMessage(flashOn?'Lanterna ligada':'Lanterna desligada')}if(e.code==='KeyE'&&started&&!inventoryOpen)interact();if(e.code==='KeyC'&&started)craft();if(e.code==='KeyM'&&started)openMap()});document.addEventListener('keyup',e=>keys[e.code]=false);$('#closeInventory').onclick=()=>{inventoryOpen=false;chestOpen=false;$('#chestPanel')?.remove();$('#inventoryPanel').classList.add('hidden');renderer.domElement.requestPointerLock?.()};$('#craftBtn').onclick=craft;$('#mapHudBtn').onclick=openMap;
function nearCabin(){return Math.hypot(camera.position.x+23,camera.position.z+20)<11}
let jumpVelocity=0;function interact(){let best=null,bd=3.1;for(const item of interactables){if(!item.object.visible)continue;const d=Math.hypot(camera.position.x-item.x,camera.position.z-item.z);if(d<bd){const dx=item.x-camera.position.x,dz=item.z-camera.position.z;const facing=(dx*-Math.sin(yaw)+dz*-Math.cos(yaw))/Math.max(d,.01);if(facing>.2){bd=d;best=item}}}if(best){if(best.type==='map'){bag.map=1;mapFound=true;best.object.visible=false;setMessage('Mapa encontrado. Pressione M para consultar e marcar locais.');updateMapPanel();updateInventory();saveGame();return}if(best.type==='key'){bag.key=1;best.object.visible=false;setMessage('Chave do laboratorio encontrada na vila.');updateInventory();saveGame();return}if(best.type==='cave'){if(!flashOn){setMessage('A mina esta escura demais. Ligue a lanterna com F.');return}camera.position.set(83,terrainHeight(83,78)+1.7,78);setMessage('Voce entrou na mina. Mantenha a lanterna acesa.');return}if(best.type==='caveExit'){camera.position.set(83,terrainHeight(83,70)+1.7,70);return}if(best.type==='labDoor'){if(!bag.key){setMessage('A porta da estacao meteorologica precisa da chave encontrada no acampamento antigo.');return}camera.position.set(0,terrainHeight(0,-99)+1.7,-99);setMessage('Voce abriu a estacao meteorologica.');return}if(best.type==='labExit'){camera.position.set(0,terrainHeight(0,-95)+1.7,-95);return}if(best.type==='shrub'){if(bag.tool<1){injuries.cuts=1;updateInventory();setMessage('Voce se cortou ao cortar o arbusto sem ferramenta.');return}const k=Math.random()<.55?'twig':'fiber';bag[k]++;progress[k]=(progress[k]||0)+1;best.object.visible=false;setMessage('Arbusto cortado: +1 '+(k==='twig'?'graveto':'fibra'));updateInventory();saveGame();return}if(best.type==='animal'){if(bag.tool<1){setMessage('Precisa de uma ferramenta para ca?ar. O animal fugiu.');best.animal.x+=7;best.animal.object.position.x+=7;return}const amt=best.animal.kind==='deer'?3:1;bag.meat+=amt;bag.hide+=best.animal.kind==='deer'?2:1;best.animal.object.visible=false;best.object.visible=false;setMessage('Carne coletada: '+amt);updateInventory();saveGame();return}if(best.type==='crop'){if(best.ready){bag.wheat+=3;best.object.visible=false;setMessage('Trigo colhido: +3.');updateInventory();saveGame()}else setMessage('A plantacao ainda esta crescendo.');return}if(best.type==='tree'){if(best.felled||best.felling){setMessage('Essa arvore ja foi derrubada.');return}if(equippedTool!=='axe'){setMessage('Equipe um machado para derrubar esta arvore.');return}best.felling=true;best.fallAt=elapsed;setMessage('Voce comecou a derrubar a arvore.');return}if(best.type==='structure'){if(best.kind==='bridge'){setMessage('A ponte esta firme. Voce atravessa com seguranca.');return}if(best.kind==='chest'){openChest();return}else{stamina=Math.min(100,stamina+45);health=Math.min(100,health+8);setMessage('Você descansou no abrigo.')}updateInventory();saveGame();return}if(best.type==='radioStation'){if(!bag.map||!clues.has('Encontrei um cabo para o transmissor. A estacao de radio fica nas montanhas, perto de -75, 58. Leve o mapa e uma bateria.')){setMessage('Consulte o mapa e as anotacoes da cabana antes de reparar o transmissor.');return}if(!radioRepaired){const missing=[['fuse','fusivel'],['cable','cabo'],['battery','bateria']].filter(([k])=>bag[k]<1).map(([,n])=>n);if(missing.length){setMessage('Ainda falta encontrar: '+missing.join(', ')+'. As anotacoes indicam o local de cada peca.');return}bag.fuse--;bag.cable--;bag.battery--;radioRepaired=true;updateInventory();saveGame();setMessage('Transmissor reparado. Siga a trilha ate o posto de apoio ao sul.');return}setMessage('Transmissor pronto. Siga para o posto de apoio ao sul.');return}if(best.type==='exit'){if(!radioRepaired){setMessage('Repare primeiro o transmissor na estacao das montanhas.');return}endGame(true,'Voce voltou a civilizacao','O transmissor confirmou sua localizacao. No posto de apoio, voce finalmente encontrou ajuda.');return}else if(best.type==='clue'){if(clues.has(best.description)){setMessage('Você já leu esta anotação.');return}clues.add(best.description);best.object.visible=false;setMessage('Pista encontrada: '+best.label);if(best.id==='log2')setMessage('O caderno da cabana indica o local do transmissor.')}else{const key=best.type==='water'?'dirty':best.type==='log'?'wood':best.type;const gained=best.amount+(selectedCharacter==='scout'?1:0);if(usedSlots({...bag,[key]:(bag[key]||0)+gained})>inventoryCapacity()){setMessage('Mochila cheia. Equipe uma mochila maior ou guarde itens no bau.');return}bag[key]=(bag[key]||0)+gained;progress[key]=(progress[key]||0)+gained;best.object.visible=false;setMessage(`+${gained} ${best.label}`)}updateInventory();saveGame();return}if(nearCabin()){stamina=Math.min(100,stamina+20);setMessage('A cabana oferece abrigo. Você descansou um pouco.');return}if(Math.hypot(camera.position.x-27,camera.position.z-35)<12&&bag.rod>0&&Math.random()<.72){bag.fish++;setMessage('Voce pescou um peixe. Cozinhe antes de comer.');updateInventory();saveGame();return}if(Math.hypot(camera.position.x-27,camera.position.z-35)<12){bag.dirty++;updateInventory();setMessage('Água coletada. Ferva-a antes de beber.');return}setMessage('Nada ao alcance. Explore a clareira e os arredores.')}
function plantCrop(x,z,remaining=45,ready=false){const crop=new THREE.Group();crop.position.set(x,terrainHeight(x,z),z);const soil=new THREE.Mesh(new THREE.BoxGeometry(1.1,.12,1.1),mats.wood);soil.position.y=.08;crop.add(soil);for(let n=0;n<5;n++){const stalk=new THREE.Mesh(new THREE.CylinderGeometry(.025,.04,.45,5),mats.grass);stalk.position.set((n-2)*.16,ready?.48:.32,0);if(ready)stalk.scale.y=2;crop.add(stalk)}scene.add(crop);interactables.push({object:crop,x,z,r:2,type:'crop',label:'Plantacao',ready,readyAt:elapsed+remaining})}
function build(kind){if(kind==='cookMeat'||kind==='cookFish'){const raw=kind==='cookMeat'?'meat':'fish',done=kind==='cookMeat'?'cooked':'cookedFish';if(!fire||Math.hypot(camera.position.x-fire.position.x,camera.position.z-fire.position.z)>4||bag[raw]<1){setMessage('Precisa de carne ou peixe cru perto de uma fogueira.');return}bag[raw]--;bag[done]++;updateInventory();setMessage('Refeicao preparada no fogo.');saveGame();return}if(kind==='bandage'){if(bag.herb<1||bag.fiber<2){setMessage('Curativo exige 1 erva e 2 fibras.');return}bag.herb--;bag.fiber-=2;bag.bandage++;updateInventory();saveGame();setMessage('Curativo fabricado.');return}if(kind==='coat'){if(bag.hide<2||bag.fiber<4){setMessage('Casaco exige 2 peles e 4 fibras.');return}bag.hide-=2;bag.fiber-=4;bag.coat=1;updateInventory();saveGame();setMessage('Casaco pronto. Ele protege do frio.');return}if(kind==='bread'){if(bag.wheat<3||!fire||Math.hypot(camera.position.x-fire.position.x,camera.position.z-fire.position.z)>4){setMessage('Fazer pao exige 3 trigos perto de uma fogueira.');return}bag.wheat-=3;bag.bread++;updateInventory();saveGame();setMessage('Pao assado pronto.');return}if(kind==='plant'){if(equippedTool!=='hoe'){setMessage('Equipe uma enxada antes de plantar.');return}if(bag.seeds<1){setMessage('Encontre sementes para plantar.');return}bag.seeds--;plantCrop(camera.position.x,camera.position.z);updateInventory();saveGame();setMessage('Semente plantada. O trigo cresce em 45 segundos.');return}if(kind==='packReinforced'&&equippedPack!=='packSimple'&&equippedPack!=='packReinforced'&&equippedPack!=='packAdvanced'){setMessage('Equipe a mochila simples antes da reforcada.');return}if(kind==='packAdvanced'&&equippedPack!=='packReinforced'&&equippedPack!=='packAdvanced'){setMessage('Equipe a mochila reforcada antes da avancada.');return}const recipe={packSimple:{fiber:8,hide:2},packReinforced:{fiber:14,hide:5,rope:2},packAdvanced:{fiber:24,hide:10,rope:4},fire:{wood:3,twig:5},shelter:{wood:10,fiber:5},cabin:{wood:20,fiber:10},chest:{wood:8},bridge:{wood:6,rope:1},rod:{twig:3,rope:1},tool:{stone:2,twig:3},axe:{stone:3,wood:2,twig:2},sword:{stone:3,wood:2},hoe:{stone:2,wood:2,twig:1},rope:{fiber:4}}[kind];if(kind==='boil'){if(bag.dirty<1||!fire||Math.hypot(camera.position.x-fire.position.x,camera.position.z-fire.position.z)>4){setMessage('Ferva água suja perto de uma fogueira.');return}bag.dirty--;bag.water++;updateInventory();setMessage('Água fervida. Agora é potável.');return}if(!recipe||Object.keys(recipe).some(k=>bag[k]<recipe[k])){setMessage('Materiais insuficientes para esta receita.');return}for(const k of Object.keys(recipe))bag[k]-=recipe[k];if(kind==='fire')makeFire(camera.position.x,camera.position.z);else if(kind==='tool'||kind==='rope'||kind==='rod'||kind==='axe'||kind==='sword'||kind==='hoe'||kind==='packSimple'||kind==='packReinforced'||kind==='packAdvanced'){bag[kind]++;if(kind==='axe'||kind==='hoe')equippedTool=kind;if(kind==='sword')equippedWeapon=kind}else makeStructure(kind,camera.position.x,camera.position.z);updateInventory();setMessage('Construção concluída.');saveGame()}
function makeStructure(kind,x,z){const g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);scene.add(g);const wood=mats.wood;if(kind==='bridge'){for(let i=-3;i<=3;i++){const plank=new THREE.Mesh(new THREE.BoxGeometry(2.4,.16,.55),wood);plank.position.set(0,.45,i*.55);g.add(plank)}}else if(kind==='chest'){const b=new THREE.Mesh(new THREE.BoxGeometry(1.4,.8,1),wood);b.position.y=.4;g.add(b)}else{for(const side of [-1,1]){const post=new THREE.Mesh(new THREE.CylinderGeometry(.09,.12,2.5,6),wood);post.position.set(side*.9,1.25,0);g.add(post)}const roof=new THREE.Mesh(new THREE.BoxGeometry(2.4,.16,2),wood);roof.position.y=2.5;g.add(roof);if(kind==='cabin'){const floor=new THREE.Mesh(new THREE.BoxGeometry(2.4,.12,2.2),wood);floor.position.y=.1;g.add(floor)}}g.traverse(o=>{if(o.isMesh)o.castShadow=true});structures.push({kind,x,z});interactables.push({object:g,x,z,r:2.5,type:'structure',kind,label:kind==='chest'?'Baú':kind==='shelter'?'Abrigo':'Cabana'})}
function craft(){const p=$('#inventoryPanel');p.classList.remove('hidden');inventoryOpen=true;document.exitPointerLock?.();let menu=$('#buildMenu');if(!menu){menu=document.createElement('div');menu.id='buildMenu';menu.className='build-menu';const recipes=[['cookMeat','Cozinhar carne - perto da fogueira'],['cookFish','Cozinhar peixe - perto da fogueira'],['bandage','Curativo - 1 erva + 2 fibras'],['coat','Casaco - 2 peles + 4 fibras'],['rod','Vara de pesca - 3 gravetos + 1 corda'],['fire','Fogueira · 3 madeira + 5 gravetos'],['shelter','Abrigo · 10 madeira + 5 fibras'],['cabin','Cabana · 20 madeira + 10 fibras'],['chest','Baú · 8 madeira'],['bridge','Ponte simples - 6 madeiras + 1 corda'],['packSimple','Mochila simples - 8 fibras + 2 peles (180 espacos)'],['packReinforced','Mochila reforcada - 14 fibras + 5 peles + 2 cordas (300 espacos)'],['packAdvanced','Mochila avancada - 24 fibras + 10 peles + 4 cordas (500 espacos)'],['axe','Machado de pedra - 3 pedras, 2 madeiras, 2 gravetos'],['sword','Espada de madeira - 3 pedras, 2 madeiras'],['hoe','Enxada - 2 pedras, 2 madeiras, 1 graveto'],['plant','Plantar sementes (precisa de enxada)'],['bread','Assar pao - 3 trigos + fogueira'],['tool','Ferramenta · 2 pedras + 3 gravetos'],['rope','Corda · 4 fibras'],['boil','Ferver água suja · junto à fogueira']];for(const [id,label] of recipes){const b=document.createElement('button');b.textContent=label;b.onclick=()=>build(id);menu.appendChild(b)}$('#craftBtn').after(menu);const style=document.createElement('style');style.textContent='.build-menu{display:grid;gap:5px;margin:8px 0}.build-menu button{background:#1d291f;color:#e4eadc;border:1px solid #ffffff20;text-align:left;padding:9px;cursor:pointer;font:10px "DM Mono",monospace}.build-menu button:hover{background:#354532}';document.head.appendChild(style)}menu.classList.remove('hidden')}
function treatInjury(kind){if(kind==='poisoning'&&bag.herb>0){bag.herb--;injuries.poisoning=0;health=Math.min(100,health+12);updateInventory();saveGame();setMessage('Intoxicacao tratada com ervas.');return}if(kind==='exhaustion'){stamina=Math.min(100,stamina+35);injuries.exhaustion=0;updateInventory();setMessage('Voce descansou e recuperou energia.');return}if(kind==='cold'&&(bag.coat||isSheltered())){injuries.cold=0;updateInventory();setMessage('Voce se aqueceu e saiu da hipotermia.');return}if(bag.bandage<1){setMessage('Fabrique um curativo com fibras e ervas.');return}if(!['cuts','bites'].includes(kind)){setMessage('Esse problema exige repouso ou ervas.');return}bag.bandage--;injuries[kind]=0;health=Math.min(100,health+16);updateInventory();saveGame();setMessage('Ferimento tratado.')}
function useItem(kind){if(!bag[kind]){setMessage('Voce nao possui esse item.');return}if(kind==='food'){bag.food--;hunger=Math.min(100,hunger+28)}else if(kind==='meat'||kind==='fish'){bag[kind]--;hunger=Math.min(100,hunger+18);injuries.poisoning=Math.max(injuries.poisoning,1);setMessage('Alimento cru: risco de intoxicacao. Use curativo ou ervas.')}else if(kind==='bread'){bag.bread--;hunger=Math.min(100,hunger+55);stamina=Math.min(100,stamina+10)}else if(kind==='cooked'||kind==='cookedFish'){bag[kind]--;hunger=Math.min(100,hunger+48);stamina=Math.min(100,stamina+12)}else if(kind==='spoiled'){bag.spoiled--;hunger=Math.min(100,hunger+5);injuries.poisoning=Math.max(injuries.poisoning,2);health=Math.max(1,health-8);setMessage('Comida estragada causou intoxicacao.')}else if(kind==='water'){bag.water--;thirst=Math.min(100,thirst+35)}else if(kind==='dirty'){bag.dirty--;thirst=Math.min(100,thirst+24);injuries.poisoning=Math.max(injuries.poisoning,1);setMessage('Agua contaminada saciou a sede, mas causou intoxicacao.')}else if(kind==='herb'){bag.herb--;health=Math.min(100,health+30);injuries.poisoning=Math.max(0,injuries.poisoning-1)}else if(kind==='mushroom'){bag.mushroom--;if(Math.random()<.4){health=Math.max(1,health-24);injuries.poisoning=Math.max(1,injuries.poisoning);setMessage('Cogumelo venenoso!')}else hunger=Math.min(100,hunger+18)}else if(kind==='bandage'){bag.bandage--;if(injuries.cuts)injuries.cuts=0;else if(injuries.bites)injuries.bites=0;else{setMessage('Voce nao tem cortes nem mordidas.');bag.bandage++;return}health=Math.min(100,health+15)}else return;updateInventory();saveGame()}

function saveGame(){try{safeStorage.set('sete-dias-save',JSON.stringify({day,timeHours,health,hunger,thirst,stamina,bag,chestStore,injuries,foodAge,cookedAge,progress,claimedGoals:[...claimedGoals],discoveredRegions:[...discoveredRegions],mapMarkers,mapFound,selectedCharacter,equippedPack,equippedWeapon,equippedTool,radioRepaired,escaped,clues:[...clues],structures,firePos:fire?{x:fire.position.x,z:fire.position.z}:null,picked:interactables.filter(i=>!i.object.visible&&i.id).map(i=>i.id),felled:interactables.filter(i=>i.felled).map(i=>i.id),crops:interactables.filter(i=>i.type==='crop'&&i.object.visible).map(i=>({x:i.x,z:i.z,ready:i.ready,remaining:Math.max(0,i.readyAt-elapsed)}))}))}catch(e){}}
