setInterval(()=>{if(started&&!gameEnded)saveGame()},15000);
function walkable(x,z){if(Math.abs(x)>123||Math.abs(z)>123)return false;return !colliders.some(c=>Math.hypot(x-c.x,z-c.z)<c.r+.38)}

function isSheltered(){return nearCabin()||structures.some(s=>(s.kind==='shelter'||s.kind==='cabin')&&Math.hypot(camera.position.x-s.x,camera.position.z-s.z)<4)}
