function updateFood(dt){if(bag.food>0||bag.meat>0||bag.fish>0)foodAge+=dt;if(bag.cooked>0||bag.cookedFish>0)cookedAge+=dt;if(foodAge>180){const lost=bag.food+bag.meat+bag.fish;if(lost){bag.spoiled+=lost;bag.food=0;bag.meat=0;bag.fish=0;foodAge=0;setMessage('A comida carregada estragou. Guarde-a no bau ou cozinhe a carne.');updateInventory()}}if(cookedAge>260){bag.spoiled+=bag.cooked+bag.cookedFish;bag.cooked=0;bag.cookedFish=0;cookedAge=0;updateInventory()}}function updateFelledTrees(){for(const i of interactables){if(i.type==='crop'&&!i.ready&&elapsed>=i.readyAt){i.ready=true;for(const c of i.object.children){c.scale.y=2;c.position.y*=1.5}setMessage('Seu trigo amadureceu. Volte para colher.')}}for(const item of interactables){if(!item.felling)continue;const p=Math.min(1,(elapsed-item.fallAt)/1.5);item.object.rotation.z=p*1.2;if(p>=1){item.felling=false;item.felled=true;item.type='log';item.label='Tronco derrubado';item.amount=5;const c=colliders.findIndex(q=>q.object===item.object);if(c>=0)colliders.splice(c,1);const fi=flora.findIndex(t=>t.root===item.object);if(fi>=0)flora.splice(fi,1);bag.twig+=2;progress.twig+=2;updateInventory();setMessage('Arvore derrubada: tronco com 5 madeiras e 2 gravetos.');saveGame()}}}
